namespace ToneCustoms.ShellStudio.Core;
public sealed class AutosaveController:IDisposable { readonly ProjectService service;readonly Func<ShellProject> getProject;readonly System.Threading.Timer timer;public AutosaveController(ProjectService service,Func<ShellProject> getProject,int seconds=120){this.service=service;this.getProject=getProject;timer=new Timer(async _=>{try{ProjectPaths.Ensure();await service.AutosaveAsync(getProject(),ProjectPaths.AppRoot);}catch{}},null,TimeSpan.FromSeconds(seconds),TimeSpan.FromSeconds(seconds));}public void Dispose()=>timer.Dispose(); }
